<template>
 <section class="insights" aria-label="研究数据看板" data-testid="dashboard-insights">
  <div class="insights-heading"><div><h3>研究数据概览</h3><p>{{ demo ? '图表样式演示' : '从资料准备到评价运行，一眼了解当前研究状态。' }}</p></div><button v-if="!dashboard && !loading" type="button" class="preview-toggle" @click="demo=!demo">{{ demo ? '返回真实统计' : '预览图表样式' }}</button></div>
  <div v-if="demo" class="demo-notice" role="status" data-testid="insights-demo-notice">演示数据，仅用于查看图表样式，不代表真实公司、研究结果或评价质量。</div>
  <div v-else-if="!dashboard && !loading" class="data-notice">统计服务暂未连接，图表保留空态。可点击“预览图表样式”查看演示。</div>
  <div class="insight-grid" :aria-busy="loading">
   <article class="insight-card task-panel">
    <div class="panel-heading"><div><h4>任务运行状态</h4><p>年报、共享法规与评价的持久化任务</p></div><SceneIcon name="task" /></div>
    <div class="task-visual">
     <div class="ring-wrap"><svg viewBox="0 0 200 200" role="img" :aria-label="ringDescription"><circle cx="100" cy="100" r="75" fill="none" stroke="#edf1f6" stroke-width="17" /><circle v-for="item in segments" :key="item.status" cx="100" cy="100" r="75" fill="none" :stroke="item.color" stroke-width="17" pathLength="100" :stroke-dasharray="item.arc+' '+(100-item.arc)" :stroke-dashoffset="-item.offset" transform="rotate(-90 100 100)" /></svg><div class="ring-center"><strong data-testid="insights-task-total">{{ totalTasks ?? '—' }}</strong><span>{{ totalTasks===0 ? '尚无任务' : '任务记录' }}</span></div></div>
     <ul class="ring-legend" data-testid="dashboard-job-statuses"><li v-for="item in statuses" :key="item.status"><span class="legend-label"><i :style="{background:item.color}" />{{ item.label }}</span><strong>{{ item.count ?? '—' }}</strong></li></ul>
    </div>
    <div class="task-summary"><span><b>{{ activeTasks ?? '—' }}</b> 项待完成</span><span><b>{{ stoppedTasks ?? '—' }}</b> 项失败或中止</span><router-link to="/tasks">查看任务</router-link></div>
   </article>
   <article class="insight-card coverage-panel">
    <div class="panel-heading"><div><h4>四维证据覆盖</h4><p>已发布成功回答中，进入上下文的来源</p></div><SceneIcon name="layers" /></div>
    <div class="source-switch" aria-label="选择证据来源"><button v-for="item in sources" :key="item.key" type="button" :aria-pressed="source===item.key" @click="source=item.key">{{ item.label }}</button></div>
    <div class="coverage-bars" data-testid="insights-coverage-bars"><div v-for="item in dimensions" :key="item.code" class="coverage-row"><div class="coverage-label"><span><em>{{ item.code }}</em>{{ item.name }}</span><strong>{{ item.ratio===null ? '—' : item.ratio+'%' }}</strong></div><div class="coverage-track" role="img" :aria-label="item.name+'：'+(item.ratio===null ? '尚无可统计的成功回答' : item.selected+' / '+item.success+'题，'+item.ratio+'%')"><span :style="{width:(item.ratio || 0)+'%'}" /></div><div class="coverage-meta">{{ item.ratio===null ? '尚无可统计的成功回答' : item.selected+' / '+item.success+' 题有入选片段' }}<span v-if="item.unknown">另有 {{ item.unknown }} 题无法校验</span></div></div></div>
    <p class="chart-caveat">统计来源入选，不代表语义支持、法规适用或质量得分。{{ data?.coverage?.truncated ? '仅含最近 '+data.coverage.inspected_runs+' 次运行。' : '重复与重试运行分别计次。' }}</p>
   </article>
   <article class="insight-card asset-panel">
    <div class="asset-copy"><span class="asset-symbol"><SceneIcon name="document" /></span><div><h4>双源资料库</h4><p>范围内年报与共享法规分别保留</p></div></div>
    <div class="asset-composition"><div class="asset-values"><span><i class="annual-dot" />年报 <b>{{ annual ?? '—' }}</b></span><span><i class="law-dot" />共享法规 <b>{{ regulation ?? '—' }}</b></span></div><div class="asset-track" role="img" :aria-label="'年报 '+(annual ?? '未知')+'，共享法规 '+(regulation ?? '未知')"><span :style="{width:documentTotal ? annual/documentTotal*100+'%' : '0%'}" /><span :style="{width:documentTotal ? regulation/documentTotal*100+'%' : '0%'}" /></div><small>{{ documentTotal===0 ? '尚未导入文档' : '法规不随公司与报告年度缩小范围' }}</small></div>
    <div class="index-number"><strong>{{ data?.counts?.ready_indexes ?? '—' }}</strong><span>就绪索引版本</span><small>业务状态，不代表模型实时可用</small></div>
   </article>
  </div>
 </section>
</template>
<script setup>
import { computed, ref, watch } from 'vue'
import SceneIcon from './SceneIcon.vue'
const props=defineProps({dashboard:{type:Object,default:null},loading:{type:Boolean,default:false}})
const demo=ref(new URLSearchParams(window.location.search).get('charts')==='demo')
watch(()=>props.dashboard,value=>{if(value)demo.value=false})
const sources=[{key:'both_context_answers',label:'双源入选'},{key:'annual_context_answers',label:'年报入选'},{key:'regulation_context_answers',label:'法规入选'}]
const source=ref('both_context_answers')
const dimensionNames=[['D1','信息披露质量'],['D2','董事会治理有效性'],['D3','内部控制与合规性'],['D4','第三方声誉']]
const sample={counts:{annual_documents:18,regulation_documents:32,ready_indexes:6},job_statuses:[{status:'succeeded',count:32},{status:'running',count:3},{status:'queued',count:5},{status:'partial',count:4},{status:'failed',count:2},{status:'cancelled',count:1},{status:'budget_exhausted',count:1}],coverage:{dimensions:dimensionNames.map(([code,name],i)=>({code,name,succeeded_answers:12,both_context_answers:[10,9,8,3][i],annual_context_answers:[12,11,10,5][i],regulation_context_answers:[11,10,9,7][i],unknown_answers:0}))}}
const data=computed(()=>props.dashboard || (demo.value ? sample : null))
const valid=n=>Number.isSafeInteger(n)&&n>=0
const definitions=[['succeeded','已完成','#438cf4'],['running','运行中','#39b8a7'],['queued','排队中','#b9c7da'],['partial','部分完成','#ac9bdb'],['failed','失败','#db8c8c'],['cancelled','已取消','#b9b9c4'],['budget_exhausted','预算耗尽','#d9b678']]
const statuses=computed(()=>definitions.map(([status,label,color])=>{const n=data.value?.job_statuses?.find(x=>x.status===status)?.count;return {status,label,color,count:valid(n)?n:null}}))
const totalTasks=computed(()=>statuses.value.every(x=>x.count!==null)?statuses.value.reduce((n,x)=>n+x.count,0):null)
const groupTotal=keys=>{const rows=statuses.value.filter(x=>keys.includes(x.status));return rows.every(x=>x.count!==null)?rows.reduce((n,x)=>n+x.count,0):null}
const activeTasks=computed(()=>groupTotal(['queued','running']))
const stoppedTasks=computed(()=>groupTotal(['failed','cancelled','budget_exhausted']))
const segments=computed(()=>{let offset=0;return statuses.value.filter(x=>x.count>0&&totalTasks.value).map(x=>{const part=x.count/totalTasks.value*100;const item={...x,arc:Math.max(0,part-Math.min(.65,part/5)),offset};offset+=part;return item})})
const ringDescription=computed(()=>totalTasks.value===null?'任务统计暂不可用':statuses.value.map(x=>x.label+' '+x.count+' 项').join('，'))
const dimensions=computed(()=>dimensionNames.map(([code,name])=>{const row=data.value?.coverage?.dimensions?.find(x=>x.code===code);const success=row?.succeeded_answers,selected=row?.[source.value];const known=valid(success)&&success>0&&valid(selected)&&selected<=success;return {code,name,success,selected,ratio:known?Math.round(selected/success*100):null,unknown:valid(row?.unknown_answers)?row.unknown_answers:0}}))
const annual=computed(()=>valid(data.value?.counts?.annual_documents)?data.value.counts.annual_documents:null)
const regulation=computed(()=>valid(data.value?.counts?.regulation_documents)?data.value.counts.regulation_documents:null)
const documentTotal=computed(()=>annual.value===null||regulation.value===null?null:annual.value+regulation.value)
</script>
